        if let Some(zero_mask) = zero_mask {
            operands.push_str(&format!(", {zero_mask}"));
        }
        let template = format!(
            "{{ .reg .pred %enable_pred; setp.ne.s32 %enable_pred, $4, 0; {prefix}{selector} {operands}; }}"
        );
